diff --git a/libarchive/archive_read_data_into_fd.c b/libarchive/archive_read_data_into_fd.c
index b63fbf9..862a973 100644
--- a/libarchive/archive_read_data_into_fd.c
+++ b/libarchive/archive_read_data_into_fd.c
@@ -31,6 +31,9 @@
 #ifdef HAVE_ERRNO_H
 #include <errno.h>
 #endif
+#ifdef HAVE_FCNTL_H
+#include <fcntl.h>
+#endif
 #ifdef HAVE_UNISTD_H
 #include <unistd.h>
 #endif
@@ -54,12 +57,11 @@ pad_to(struct archive *a, int fd, int can_lseek,
 	ssize_t bytes_written;

 	if (can_lseek) {
+		/* Entry offsets are relative; lseek returns an absolute offset. */
 		actual_offset = lseek(fd,
 		    target_offset - actual_offset, SEEK_CUR);
-		if (actual_offset != target_offset) {
-			archive_set_error(a,
-			    actual_offset == -1 ? errno : ARCHIVE_ERRNO_MISC,
-			    "Seek error");
+		if (actual_offset == -1) {
+			archive_set_error(a, errno, "Seek error");
 			return (ARCHIVE_FATAL);
 		}
 		return (ARCHIVE_OK);
@@ -95,7 +97,6 @@ archive_read_data_into_fd(struct archive *a, int fd)
 	const void *buff;
 	size_t size, bytes_to_write;
 	ssize_t bytes_written;
-	int64_t fd_offset;
 	int64_t target_offset = 0;
 	int64_t actual_offset = 0;
 	int64_t declared_size;
@@ -108,9 +109,16 @@ archive_read_data_into_fd(struct archive *a, int fd)
 	declared_size = ((struct archive_read *)a)->entry_bytes_declared;

 	can_lseek = (fstat(fd, &st) == 0) && S_ISREG(st.st_mode);
+	/* Append writes ignore seeks, so holes must be written as zeroes. */
+#if defined(F_GETFL) && defined(O_APPEND)
+	if (can_lseek) {
+		int flags = fcntl(fd, F_GETFL);
+		if (flags == -1 || (flags & O_APPEND) != 0)
+			can_lseek = 0;
+	}
+#endif
 	if (can_lseek) {
-		fd_offset = lseek(fd, 0, SEEK_CUR);
-		if (fd_offset == -1)
+		if (lseek(fd, 0, SEEK_CUR) == -1)
 			can_lseek = 0;
 	}

@@ -193,15 +201,5 @@ cleanup:
 	free(nulls);
 	if (r != ARCHIVE_EOF)
 		return (r);
-	r = ARCHIVE_OK;
-	if (can_lseek) {
-		int64_t offset = lseek(fd, 0, SEEK_CUR);
-		if (offset - fd_offset != actual_offset) {
-			archive_set_error(a,
-			    offset == -1 ? errno : ARCHIVE_ERRNO_MISC,
-			    "Seek error");
-			r = ARCHIVE_FATAL;
-		}
-	}
-	return (r);
+	return (ARCHIVE_OK);
 }
diff --git a/libarchive/test/test_read_data_large.c b/libarchive/test/test_read_data_large.c
index 3718234..f3f5860 100644
--- a/libarchive/test/test_read_data_large.c
+++ b/libarchive/test/test_read_data_large.c
@@ -110,6 +110,49 @@ DEFINE_TEST(test_read_data_large)
 	assertEqualMem(buff2, buff3, sizeof(buff3));
 }

+/* O_APPEND may advance the descriptor past a preexisting prefix. */
+DEFINE_TEST(test_read_data_into_fd_append)
+{
+	struct archive *a;
+	struct archive_entry *ae;
+	char buffer[10240];
+	size_t used;
+	int fd, i;
+
+	assert((a = archive_write_new()) != NULL);
+	assertEqualIntA(a, ARCHIVE_OK, archive_write_set_format_ustar(a));
+	assertEqualIntA(a, ARCHIVE_OK,
+	    archive_write_open_memory(a, buffer, sizeof(buffer), &used));
+	assert((ae = archive_entry_new()) != NULL);
+	archive_entry_set_mode(ae, S_IFREG | 0644);
+	archive_entry_set_size(ae, 5);
+	for (i = 0; i < 2; ++i) {
+		archive_entry_set_pathname(ae, i == 0 ? "first" : "second");
+		assertEqualIntA(a, ARCHIVE_OK, archive_write_header(a, ae));
+		assertEqualIntA(a, 5, archive_write_data(a, "entry", 5));
+	}
+	archive_entry_free(ae);
+	assertEqualIntA(a, ARCHIVE_OK, archive_write_close(a));
+	assertEqualInt(ARCHIVE_OK, archive_write_free(a));
+
+	assertMakeFile("append", 0644, "prefix");
+	fd = open("append", O_WRONLY | O_APPEND | O_BINARY);
+	assert(fd >= 0);
+	assertEqualInt(0, lseek(fd, 0, SEEK_SET));
+	assert((a = archive_read_new()) != NULL);
+	assertEqualIntA(a, ARCHIVE_OK, archive_read_support_format_tar(a));
+	assertEqualIntA(a, ARCHIVE_OK,
+	    archive_read_open_memory(a, buffer, used));
+	for (i = 0; i < 2; ++i) {
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_next_header(a, &ae));
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_data_into_fd(a, fd));
+	}
+	assertEqualIntA(a, ARCHIVE_EOF, archive_read_next_header(a, &ae));
+	assertEqualInt(ARCHIVE_OK, archive_read_free(a));
+	close(fd);
+	assertFileContents("prefixentryentry", 16, "append");
+}
+
 #define	FILE_SIZE	0x90000		/* 576 KiB total logical size */

 static char sparse_buff[0x10000];	/* Holds the (small) stored archive. */
@@ -128,7 +171,8 @@ DEFINE_TEST(test_read_data_into_fd_sparse)
 	struct archive_entry *ae;
 	size_t archive_size = 0;
 	const char *skip_sparse_tests;
-	int fd;
+	int fd, mode;
+	FILE *f;

 	skip_sparse_tests = getenv("SKIP_TEST_SPARSE");
 	if (skip_sparse_tests != NULL) {
@@ -168,35 +212,51 @@ DEFINE_TEST(test_read_data_into_fd_sparse)
 	assertEqualIntA(a, ARCHIVE_OK, archive_write_close(a));
 	assertEqualInt(ARCHIVE_OK, archive_write_free(a));

-	/* Read it back and extract it into a real file descriptor. */
-	assert((a = archive_read_new()) != NULL);
-	assertEqualIntA(a, ARCHIVE_OK, archive_read_support_format_all(a));
-	assertEqualIntA(a, ARCHIVE_OK, archive_read_support_filter_all(a));
-	assertEqualIntA(a, ARCHIVE_OK,
-	    archive_read_open_memory(a, sparse_buff, archive_size));
-	assertEqualIntA(a, ARCHIVE_OK, archive_read_next_header(a, &ae));
-	assertEqualInt(FILE_SIZE, archive_entry_size(ae));
-
-	fd = open("file", O_WRONLY | O_CREAT | O_BINARY, 0644);
-	assert(fd >= 0);
+	/* Exercise holes at offset zero, after a prefix, and with O_APPEND. */
+	for (mode = 0; mode < 3; ++mode) {
+		const char *name = mode == 0 ? "file" :
+		    mode == 1 ? "prefixed" : "append";
+		int prefix_size = mode == 0 ? 0 : 6;

-	assertEqualIntA(a, ARCHIVE_OK, archive_read_data_into_fd(a, fd));
+#if !defined(F_GETFL)
+		/* Sparse append support requires querying the descriptor flags. */
+		if (mode == 2)
+			break;
+#endif
+		assert((a = archive_read_new()) != NULL);
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_support_format_all(a));
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_support_filter_all(a));
+		assertEqualIntA(a, ARCHIVE_OK,
+		    archive_read_open_memory(a, sparse_buff, archive_size));
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_next_header(a, &ae));
+		assertEqualInt(FILE_SIZE, archive_entry_size(ae));

-	/*
-	 * archive_read_data_into_fd() seeks over the trailing hole but, like
-	 * a regular extraction, leaves the on-disk size short. Truncate up
-	 * to the full size to realize the final hole, as a consumer does.
-	 */
-	assert(ftruncate(fd, FILE_SIZE) != -1);
-	close(fd);
+		assertMakeFile(name, 0644, prefix_size ? "prefix" : "");
+		fd = open(name, O_WRONLY | O_BINARY |
+		    (mode == 2 ? O_APPEND : 0));
+		assert(fd >= 0);
+		/* O_APPEND must work even when the initial position is zero. */
+		if (mode == 1)
+			assertEqualInt(prefix_size, lseek(fd, prefix_size, SEEK_SET));
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_data_into_fd(a, fd));

-	assertEqualIntA(a, ARCHIVE_OK, archive_read_close(a));
-	assertEqualInt(ARCHIVE_OK, archive_read_free(a));
+		/* Seeking over a trailing hole requires the consumer to extend
+		 * the file. Append output instead materializes all the zeroes. */
+		if (mode != 2)
+			assertEqualInt(0, ftruncate(fd, prefix_size + FILE_SIZE));
+		close(fd);
+		assertEqualIntA(a, ARCHIVE_OK, archive_read_close(a));
+		assertEqualInt(ARCHIVE_OK, archive_read_free(a));

-	/*
-	 * The reconstructed file must match byte for byte: data regions
-	 * are 'a', every hole (including the trailing one) is zero.
-	 */
-	assertFileSize("file", FILE_SIZE);
-	assertFileContents(sparse_expected, FILE_SIZE, "file");
+		assertFileSize(name, prefix_size + FILE_SIZE);
+		f = fopen(name, "rb");
+		assert(f != NULL);
+		if (prefix_size) {
+			assertEqualInt(prefix_size, fread(buff3, 1, prefix_size, f));
+			assertEqualMem("prefix", buff3, prefix_size);
+		}
+		assertEqualInt(FILE_SIZE, fread(buff3, 1, FILE_SIZE, f));
+		assertEqualMem(sparse_expected, buff3, FILE_SIZE);
+		fclose(f);
+	}
 }
